    fun loadDynamicTranslations(context: Context) {
        try {
            val inputStream: InputStream = context.assets.open("content_translations.json")
            val size = inputStream.available()
            val buffer = ByteArray(size)
            inputStream.read(buffer)
            inputStream.close()
            val jsonStr = String(buffer, Charsets.UTF_8)
            
            val jsonObject = JSONObject(jsonStr)
            val keys = jsonObject.keys()
            while (keys.hasNext()) {
                val key = keys.next()
                val langMapObj = jsonObject.getJSONObject(key)
                val langMap = mutableMapOf<String, String>()
                val langKeys = langMapObj.keys()
                while (langKeys.hasNext()) {
                    val lang = langKeys.next()
                    langMap[lang] = langMapObj.getString(lang)
                }
                dictionary[key] = langMap
            }
        } catch (e: Exception) {
            e.printStackTrace()
        }
    }
